#include "semantic.h"

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct mt_builder_stream { uint8_t *data; uint32_t size; } mt_builder_stream;
typedef struct mt_msf_builder { uint32_t block_size; mt_builder_stream *streams; size_t stream_count; size_t stream_capacity; } mt_msf_builder;

static uint32_t mt_builder_blocks(uint32_t size,uint32_t block_size){return size==0u?0u:1u+(size-1u)/block_size;}
mt_status mt_msf_builder_init(mt_msf_builder *builder,uint32_t block_size){if(builder==NULL||block_size<512u||(block_size&(block_size-1u))!=0u)return MT_ERR_ARGUMENT;builder->block_size=block_size;builder->streams=NULL;builder->stream_count=0u;builder->stream_capacity=0u;return MT_OK;}
void mt_msf_builder_dispose(mt_msf_builder *builder){if(builder==NULL)return;for(size_t i=0u;i<builder->stream_count;++i)free(builder->streams[i].data);free(builder->streams);builder->streams=NULL;builder->stream_count=0u;builder->stream_capacity=0u;builder->block_size=0u;}
static mt_status mt_builder_reserve(mt_msf_builder *builder,size_t capacity){if(capacity<=builder->stream_capacity)return MT_OK;size_t next=builder->stream_capacity==0u?8u:builder->stream_capacity;while(next<capacity){if(next>SIZE_MAX/2u){next=capacity;break;}next*=2u;}if(next>SIZE_MAX/sizeof(mt_builder_stream))return MT_ERR_NOMEM;mt_builder_stream *streams=(mt_builder_stream*)realloc(builder->streams,next*sizeof(*streams));if(streams==NULL)return MT_ERR_NOMEM;for(size_t i=builder->stream_capacity;i<next;++i)streams[i]=(mt_builder_stream){NULL,0u};builder->streams=streams;builder->stream_capacity=next;return MT_OK;}
mt_status mt_msf_builder_add_stream(mt_msf_builder *builder,const uint8_t *data,size_t size,uint32_t *out_index){if(builder==NULL||(data==NULL&&size!=0u)||out_index==NULL||size>UINT32_MAX)return MT_ERR_ARGUMENT;mt_status s=mt_builder_reserve(builder,builder->stream_count+1u);if(s!=MT_OK)return s;uint8_t *copy=NULL;if(size!=0u){copy=(uint8_t*)malloc(size);if(copy==NULL)return MT_ERR_NOMEM;memcpy(copy,data,size);}builder->streams[builder->stream_count]=(mt_builder_stream){copy,(uint32_t)size};*out_index=(uint32_t)builder->stream_count++;return MT_OK;}
mt_status mt_msf_builder_replace_stream(mt_msf_builder *builder,uint32_t index,const uint8_t *data,size_t size){if(builder==NULL||index>=builder->stream_count||(data==NULL&&size!=0u)||size>UINT32_MAX)return MT_ERR_ARGUMENT;uint8_t *copy=NULL;if(size!=0u){copy=(uint8_t*)malloc(size);if(copy==NULL)return MT_ERR_NOMEM;memcpy(copy,data,size);}free(builder->streams[index].data);builder->streams[index]=(mt_builder_stream){copy,(uint32_t)size};return MT_OK;}

mt_status mt_msf_builder_measure(const mt_msf_builder *builder,size_t *out_size,uint32_t *out_blocks){if(builder==NULL||out_size==NULL||out_blocks==NULL)return MT_ERR_ARGUMENT;uint64_t directory_bytes=4u+4u*builder->stream_count;uint64_t stream_blocks=0u;for(size_t i=0u;i<builder->stream_count;++i){uint32_t blocks=mt_builder_blocks(builder->streams[i].size,builder->block_size);directory_bytes+=(uint64_t)blocks*4u;stream_blocks+=blocks;}uint32_t directory_blocks=mt_builder_blocks((uint32_t)directory_bytes,builder->block_size);uint64_t blocks=3u+1u+directory_blocks+stream_blocks;if(blocks>UINT32_MAX||blocks>SIZE_MAX/builder->block_size)return MT_ERR_NOMEM;*out_blocks=(uint32_t)blocks;*out_size=(size_t)blocks*builder->block_size;return MT_OK;}

static void mt_store_u32(uint8_t *p,uint32_t value){p[0]=(uint8_t)value;p[1]=(uint8_t)(value>>8u);p[2]=(uint8_t)(value>>16u);p[3]=(uint8_t)(value>>24u);}

mt_status mt_msf_builder_write(const mt_msf_builder *builder,uint8_t *output,size_t capacity,size_t *out_size){if(builder==NULL||output==NULL||out_size==NULL)return MT_ERR_ARGUMENT;size_t total;uint32_t block_count;mt_status s=mt_msf_builder_measure(builder,&total,&block_count);if(s!=MT_OK)return s;if(capacity<total)return MT_ERR_NOMEM;memset(output,0,total);static const uint8_t magic[32]={0x4d,0x69,0x63,0x72,0x6f,0x73,0x6f,0x66,0x74,0x20,0x43,0x2f,0x43,0x2b,0x2b,0x20,0x4d,0x53,0x46,0x20,0x37,0x2e,0x30,0x30,0x0d,0x0a,0x1a,0x44,0x53,0x00,0x00,0x00};memcpy(output,magic,32u);uint64_t directory_bytes=4u+4u*builder->stream_count;uint32_t stream_blocks_total=0u;for(size_t i=0u;i<builder->stream_count;++i){uint32_t blocks=mt_builder_blocks(builder->streams[i].size,builder->block_size);directory_bytes+=(uint64_t)blocks*4u;stream_blocks_total+=blocks;}uint32_t directory_blocks=mt_builder_blocks((uint32_t)directory_bytes,builder->block_size);mt_store_u32(output+32u,builder->block_size);mt_store_u32(output+36u,1u);mt_store_u32(output+40u,block_count);mt_store_u32(output+44u,(uint32_t)directory_bytes);mt_store_u32(output+48u,0u);mt_store_u32(output+52u,3u);
    uint32_t directory_first=4u;for(uint32_t i=0u;i<directory_blocks;++i)mt_store_u32(output+(size_t)3u*builder->block_size+i*4u,directory_first+i);
    uint8_t *directory=(uint8_t*)calloc(directory_blocks,builder->block_size);if(directory==NULL)return MT_ERR_NOMEM;size_t pos=0u;mt_store_u32(directory+pos,(uint32_t)builder->stream_count);pos+=4u;for(size_t i=0u;i<builder->stream_count;++i){mt_store_u32(directory+pos,builder->streams[i].size);pos+=4u;}uint32_t next_block=directory_first+directory_blocks;for(size_t i=0u;i<builder->stream_count;++i){uint32_t blocks=mt_builder_blocks(builder->streams[i].size,builder->block_size);for(uint32_t j=0u;j<blocks;++j){mt_store_u32(directory+pos,next_block+j);pos+=4u;}next_block+=blocks;}for(uint32_t i=0u;i<directory_blocks;++i)memcpy(output+(size_t)(directory_first+i)*builder->block_size,directory+(size_t)i*builder->block_size,builder->block_size);free(directory);next_block=directory_first+directory_blocks;for(size_t i=0u;i<builder->stream_count;++i){uint32_t blocks=mt_builder_blocks(builder->streams[i].size,builder->block_size);for(uint32_t j=0u;j<blocks;++j){size_t source=(size_t)j*builder->block_size;size_t remaining=builder->streams[i].size-source;size_t amount=remaining<builder->block_size?remaining:builder->block_size;memcpy(output+(size_t)(next_block+j)*builder->block_size,builder->streams[i].data+source,amount);}next_block+=blocks;}*out_size=total;(void)stream_blocks_total;return MT_OK;}
